import { createHash } from "node:crypto";

const SENSITIVE_KEY = /^(raw[_-]?prompt|messages?|body|authorization|api[_-]?key|headers?)$/i;
const SENSITIVE_VALUE = /(?:\bsk-[A-Za-z0-9_-]{8,}|\bphc_[A-Za-z0-9_-]{8,}|\bghp_[A-Za-z0-9_-]{8,}|\bAKIA[A-Z0-9]{12,}|-----BEGIN [A-Z ]*PRIVATE KEY-----|\bBearer\s+[A-Za-z0-9._~+\/-]+=*)/i;
const SHELL_METACHARACTERS = /[;&|`$><\n\r]/;
const ROUTE_PATTERN = /^\/[A-Za-z0-9._~!$&'()*+,;=:@%/-]*$/;
const COMMAND_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/;
const RUN_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/;

function canonicalize(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalize).join(",")}]`;
  if (value && typeof value === "object") {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalize(value[key])}`).join(",")}}`;
  }
  return JSON.stringify(value);
}

function sha256(value) {
  return createHash("sha256").update(value).digest("hex");
}

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function findSensitive(value, path = "trace") {
  if (typeof value === "string") {
    return SENSITIVE_VALUE.test(value) ? { path, reason: "credential-like-value" } : undefined;
  }
  if (Array.isArray(value)) {
    for (let index = 0; index < value.length; index += 1) {
      const found = findSensitive(value[index], `${path}[${index}]`);
      if (found) return found;
    }
    return undefined;
  }
  if (isPlainObject(value)) {
    for (const [key, child] of Object.entries(value)) {
      if (SENSITIVE_KEY.test(key)) return { path: `${path}.${key}`, reason: `sensitive-field:${key}` };
      const found = findSensitive(child, `${path}.${key}`);
      if (found) return found;
    }
  }
  return undefined;
}

function readString(object, names) {
  for (const name of names) {
    if (typeof object?.[name] === "string" && object[name].trim()) return object[name].trim();
  }
  return undefined;
}

function normalizeKind(value) {
  return value === "command-id" ? "command-id" : value === "route" ? "route" : value === "scenario" ? "scenario" : undefined;
}

function validateReproducer(reproducer) {
  if (!isPlainObject(reproducer)) return { error: "reproducer must be an object" };
  const kind = normalizeKind(reproducer.kind);
  if (!kind) return { error: "reproducer.kind must be scenario, route, or command-id" };
  const value = readString(reproducer, ["value", "id", "path", "scenario", "commandId"]);
  if (!value) return { error: "reproducer value is required" };
  if (value.length > 512) return { error: "reproducer is not bounded" };
  if (SHELL_METACHARACTERS.test(value)) return { error: "reproducer must not contain shell syntax" };
  if (kind === "route" && !ROUTE_PATTERN.test(value)) return { error: "route reproducer is invalid" };
  if (kind === "command-id" && !COMMAND_ID_PATTERN.test(value)) return { error: "command-id reproducer is invalid" };
  return { kind, value };
}

function validateSelector(selector) {
  if (!isPlainObject(selector)) return { error: "selector must be an object" };
  const runId = readString(selector, ["runId"]);
  const attemptValue = selector.attempt;
  const attempt = typeof attemptValue === "string" && /^\d+$/.test(attemptValue) ? Number(attemptValue) : attemptValue;
  if (!runId || !RUN_ID_PATTERN.test(runId)) return { error: "selector.runId is invalid" };
  if (!Number.isSafeInteger(attempt) || attempt < 0) return { error: "selector.attempt is invalid" };
  return { runId, attempt };
}

function outcomeOf(trace) {
  const outcome = readString(trace, ["outcome", "status", "result", "classification"]);
  if (outcome) return outcome.toLowerCase();
  if (trace?.failure === true || trace?.failed === true) return "failure";
  if (trace?.success === true) return "success";
  return "unknown";
}

function isFailure(outcome) {
  return ["failure", "failed", "fail", "error", "exception", "timeout"].includes(outcome);
}

function isProtectedSuccess(outcome) {
  return ["success", "successful", "passed", "pass", "rejected", "reject", "cancelled", "canceled", "cancel"].includes(outcome);
}

function digestFor(trace, reproducer, selector) {
  const before = readString(trace, ["beforeFixDigest", "beforeFix", "before"]);
  const after = readString(trace, ["afterFixDigest", "afterFix", "after"]);
  return sha256(canonicalize({
    reproducer,
    selector,
    beforeFix: before ?? null,
    afterFix: after ?? null,
  }));
}

/**
 * Convert one explicitly selected, already-redacted trace into a replayable eval sample.
 * The function is pure and deliberately rejects the complete trace when any sensitive
 * field or credential-like value is present.
 */
export function convertTraceToEvalSample(trace, options = {}) {
  if (!isPlainObject(trace)) {
    return { ok: false, rejected: true, diagnostic: { code: "INVALID_TRACE", message: "trace must be an object" } };
  }
  const sensitive = findSensitive(trace);
  if (sensitive) {
    return {
      ok: false,
      rejected: true,
      diagnostic: { code: "UNREDACTED_TRACE", message: "trace contains unredacted sensitive data", path: sensitive.path, reason: sensitive.reason },
    };
  }
  const reproducer = validateReproducer(trace.reproducer ?? options.reproducer);
  if (reproducer.error) return { ok: false, rejected: true, diagnostic: { code: "INVALID_REPRODUCER", message: reproducer.error } };
  const selector = validateSelector(trace.selector ?? options.selector);
  if (selector.error) return { ok: false, rejected: true, diagnostic: { code: "INVALID_SELECTOR", message: selector.error } };

  const outcome = outcomeOf(trace);
  if (!isFailure(outcome) && !isProtectedSuccess(outcome)) {
    return { ok: false, rejected: true, diagnostic: { code: "UNKNOWN_OUTCOME", message: `unsupported trace outcome: ${outcome}` } };
  }
  const failed = isFailure(outcome);
  const sample = {
    version: 1,
    expectations: {
      "before-fix": failed ? "fail" : "pass",
      "after-fix": "pass",
    },
    outcome: failed ? "failure" : "protected-success",
    reproducer: { kind: reproducer.kind, value: reproducer.value },
    selector: { runId: selector.runId, attempt: selector.attempt },
    digest: digestFor(trace, reproducer, selector),
  };
  if (options.id) sample.id = String(options.id);
  return { ok: true, sample };
}

/** Convert only the supplied traces. Every rejection is reported independently. */
export function convertSelectedTraces(traces, options = {}) {
  if (!Array.isArray(traces)) throw new TypeError("traces must be an array");
  const samples = [];
  const rejected = [];
  traces.forEach((trace, index) => {
    const result = convertTraceToEvalSample(trace, options);
    if (result.ok) samples.push(result.sample);
    else rejected.push({ index, ...result.diagnostic });
  });
  return { samples, rejected };
}

export function convertTracesToEvalSamples(traces, options = {}) {
  return convertSelectedTraces(traces, options);
}

export function traceToEvalSample(trace, options = {}) {
  return convertTraceToEvalSample(trace, options);
}

export default convertSelectedTraces;

export type ReproducerKind = "scenario" | "route" | "command-id";

export interface EvalReproducer {
  kind: ReproducerKind;
  value: string;
}

export interface EvalSelector {
  runId: string;
  attempt: number;
}

export interface EvalSample {
  version: 1;
  id?: string;
  expectations: {
    "before-fix": "fail" | "pass";
    "after-fix": "pass";
  };
  outcome: "failure" | "protected-success";
  reproducer: EvalReproducer;
  selector: EvalSelector;
  digest: string;
}

export interface ConversionDiagnostic {
  code: "INVALID_TRACE" | "UNREDACTED_TRACE" | "INVALID_REPRODUCER" | "INVALID_SELECTOR" | "UNKNOWN_OUTCOME";
  message: string;
  path?: string;
  reason?: string;
}\n
export type ConversionResult =
  | { ok: true; sample: EvalSample }
  | { ok: false; rejected: true; diagnostic: ConversionDiagnostic };

export interface BatchRejection extends ConversionDiagnostic {
  index: number;
}

export interface BatchResult {
  samples: EvalSample[];
  rejected: BatchRejection[];
}

export function convertTraceToEvalSample(trace: unknown, options?: { id?: string; reproducer?: unknown; selector?: unknown }): ConversionResult;
export function convertSelectedTraces(traces: unknown[], options?: { id?: string; reproducer?: unknown; selector?: unknown }): BatchResult;
export function convertTracesToEvalSamples(traces: unknown[], options?: { id?: string; reproducer?: unknown; selector?: unknown }): BatchResult;
export function traceToEvalSample(trace: unknown, options?: { id?: string; reproducer?: unknown; selector?: unknown }): ConversionResult;

export default function convertSelectedTraces(traces: unknown[], options?: { id?: string; reproducer?: unknown; selector?: unknown }): BatchResult;

